pub const QueueProxy = QueueProxyWithCustomDispatch(DeviceDispatch);
pub fn QueueProxyWithCustomDispatch(DispatchType: type) type {
    return struct {
        const Self = @This();
        pub const Wrapper = DeviceWrapperWithCustomDispatch(DispatchType);

        handle: Queue,
        wrapper: *const Wrapper,

        pub fn init(handle: Queue, wrapper: *const Wrapper) Self {
            return .{
                .handle = handle,
                .wrapper = wrapper,
            };
        }
        pub const QueueSubmitError = Wrapper.QueueSubmitError;
        pub fn submit(
            self: Self,
